177	    @Test
178	    void write_versionConflict_returns409() throws Exception {
179	        register("eq-ver", 100);
180	        addReading("eq-ver", "add-v1", 99, "r1", "2026-01-01T10:00:00Z", 10, 409);
181	        // 失败的写操作不改变版本
