350	    @Test
351	    void idempotency_replayMismatchAndFailureNotOccupying() throws Exception {
352	        register("eq-idem", 1000);
353	
354	        MvcResult first = postJson("/api/equipment/eq-idem/readings", """
355	                {"requestId":"idem-1","expectedVersion":1,"readingId":"r1",
356	                 "sampledAt":"2026-01-01T10:00:00Z","cumulativeMinutes":100}
357	                """);
358	        assert first.getResponse().getStatus() == 201;
359	
360	        // 同键同参：重放原成功结果，业务效果不重复
361	        MvcResult replay = postJson("/api/equipment/eq-idem/readings", """
362	                {"requestId":"idem-1","expectedVersion":1,"readingId":"r1",
363	                 "sampledAt":"2026-01-01T10:00:00Z","cumulativeMinutes":100}
364	                """);
365	        assert replay.getResponse().getStatus() == 201;
366	        assert replay.getResponse().getContentAsString()
367	                .equals(first.getResponse().getContentAsString());
368	        mockMvc.perform(get("/api/equipment/eq-idem/readings"))
369	                .andExpect(jsonPath("$", hasSize(1)));
370	        mockMvc.perform(get("/api/equipment/eq-idem/status"))
371	                .andExpect(jsonPath("$.version").value(2));
372	
373	        // 同键异参 → 409
374	        mockMvc.perform(post("/api/equipment/eq-idem/readings")
375	                        .contentType(MediaType.APPLICATION_JSON)
376	                        .content("""
377	                                {"requestId":"idem-1","expectedVersion":1,"readingId":"r1",
378	                                 "sampledAt":"2026-01-01T10:00:00Z","cumulativeMinutes":101}
379	                                """))
380	                .andExpect(status().isConflict())
381	                .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));
382	
383	        // 失败不占键：422 后同 requestId 修正参数可成功
384	        addReading("eq-idem", "idem-2", 2, "r2", "2026-01-01T11:00:00Z", 50, 422);
385	        addReading("eq-idem", "idem-2", 2, "r2", "2026-01-01T11:00:00Z", 150, 201);
386	
387	        // 版本冲突失败同样不占键
388	        addReading("eq-idem", "idem-3", 99, "r3", "2026-01-01T12:00:00Z", 200, 409);
389	        addReading("eq-idem", "idem-3", 3, "r3", "2026-01-01T12:00:00Z", 200, 201);
390	
391	        mockMvc.perform(get("/api/equipment/eq-idem/readings"))
392	                .andExpect(jsonPath("$", hasSize(3)));
393	    }
