package com.example.starter.maintenance.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 材料批次。撤销只置状态，批次标识与历史引用永不删除。
 *
 * @param materialId    材料批次号，全局唯一
 * @param materialName  材料名称
